mapper.select:
SELECT keeper_id, keeper_code, keeper_name,login_name,keeper_gender, IF(keeper_id_card_number,CONCAT(SUBSTRING(keeper_id_card_number,1,6),'********',SUBSTRING(keeper_id_card_number,15)),NULL) AS keeper_id_card_number, CONCAT(SUBSTRING(keeper_phone_number,1,3),'****',SUBSTRING(keeper_phone_number,8)) AS keeper_phone_number, keeper_email,status,longitude,latitude,province_id,city_id,county_id,location_flag,keeper_type,(case when TIMESTAMPDIFF(MINUTE,take_point_time,now())<5 then '1' else '0' end) as is_line FROM bm_gridkeeper a WHERE a.delete_flag = 0 ${dataScope}
and a.keeper_id in (select r.keeper_id from bm_grid_keeper_ref r where r.delete_flag = '0' and r.grid_id = #{deptId,jdbcType=VARCHAR} )
and a.province_id = #{provinceId,jdbcType=VARCHAR}
and a.city_id = #{cityId,jdbcType=VARCHAR}
and a.status = #{status}
and a.keeper_code like concat('%',#{keeperCode},'%')
and a.keeper_name like concat('%',#{keeperName},'%')
and a.login_name like concat('%',#{loginName},'%')
and a.keeper_phone_number like concat('%',#{keeperPhoneNumber},'%')
and EXISTS(SELECT b.keeper_id FROM bm_grid_keeper_ref b WHERE b.delete_flag = '0' and b.grid_id = #{gridId} AND b.keeper_id = a.keeper_id)
and (a.keeper_code like concat('%',#{keyword},'%') or a.keeper_name like concat('%',#{keyword},'%') or a.login_name like concat('%',#{keyword},'%'))
and a.location_flag = #{locationFlag}
and a.keeper_type = #{keeperType}
order by a.create_time DESC,a.keeper_id DESC

SELECT DISTINCT a.keeper_id, a.keeper_code, a.keeper_name, a.login_name, a.keeper_gender, c.color, c.grid_id, a.staff_id as userId, IF ( a.keeper_id_card_number, CONCAT( SUBSTRING( a.keeper_id_card_number, 1, 6 ), '********', SUBSTRING( a.keeper_id_card_number, 15 )), NULL ) AS keeper_id_card_number, a.keeper_phone_number aesPhoneNumber, CONCAT( SUBSTRING( a.keeper_phone_number, 1, 3 ), '****', SUBSTRING( a.keeper_phone_number, 8 )) AS keeper_phone_number, a.keeper_email, a.STATUS, a.longitude, a.latitude, a.province_id, a.city_id, a.county_id, a.location_flag, a.keeper_type, (case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as is_line, sys.AVATAR keeperPhotoUrl FROM bm_gridkeeper a, bm_grid_keeper_ref b, bm_grid c, sys_user sys WHERE a.delete_flag = 0 AND b.delete_flag = 0 AND a.keeper_id = b.keeper_id and b.grid_id=c.grid_id and a.industry_code = c.industry_code and a.staff_id = sys.USER_ID
and a.province_id = #{provinceId,jdbcType=VARCHAR}
and a.city_id = #{cityId,jdbcType=VARCHAR}
and a.status = #{status}
and a.keeper_code like concat('%',#{keeperCode,jdbcType=VARCHAR},'%')
and a.keeper_name like concat('%',#{keeperName,jdbcType=VARCHAR},'%')
and a.login_name like concat('%',#{loginName,jdbcType=VARCHAR},'%')
and a.keeper_phone_number like concat('%',#{keeperPhoneNumber,jdbcType=VARCHAR},'%')
and c.grid_level_code like concat('%',#{gridLevelCode,jdbcType=VARCHAR},'%')
and b.grid_id = #{gridId,jdbcType=VARCHAR}
and (a.keeper_code like concat('%',#{keyword,jdbcType=VARCHAR},'%') or a.keeper_name like concat('%',#{keyword},'%'))
and a.location_flag = #{locationFlag,jdbcType=VARCHAR}
and a.keeper_type = #{keeperType,jdbcType=VARCHAR}
${dataScope} order by a.keeper_sort

SELECT DISTINCT a.keeper_id, a.keeper_code, a.keeper_name, a.login_name, a.keeper_gender, GROUP_CONCAT(c.grid_id) as gridId, a.staff_id as userId, IF ( a.keeper_id_card_number, CONCAT( SUBSTRING( a.keeper_id_card_number, 1, 6 ), '********', SUBSTRING( a.keeper_id_card_number, 15 )), NULL ) AS keeper_id_card_number, a.keeper_phone_number aesPhoneNumber, CONCAT( SUBSTRING( a.keeper_phone_number, 1, 3 ), '****', SUBSTRING( a.keeper_phone_number, 8 )) AS keeper_phone_number, a.keeper_email, a.STATUS, a.longitude, a.latitude, a.province_id, a.city_id, a.county_id, a.location_flag, a.keeper_type, (case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as is_line, sys.AVATAR keeperPhotoUrl FROM bm_gridkeeper a, bm_grid_keeper_ref b, bm_grid c, sys_user sys WHERE a.delete_flag = 0 AND b.delete_flag = 0 AND a.keeper_id = b.keeper_id and b.grid_id=c.grid_id and a.industry_code = c.industry_code and a.staff_id = sys.USER_ID
and a.province_id = #{provinceId,jdbcType=VARCHAR}
and a.city_id = #{cityId,jdbcType=VARCHAR}
and a.status = #{status}
and a.keeper_code like concat('%',#{keeperCode},'%')
and a.keeper_name like concat('%',#{keeperName},'%')
and a.login_name like concat('%',#{loginName},'%')
and a.keeper_phone_number like concat('%',#{keeperPhoneNumber},'%')
and c.grid_level_code like concat('%',#{gridLevelCode},'%')
and b.grid_id = #{gridId}
and (a.keeper_code like concat('%',#{keyword},'%') or a.keeper_name like concat('%',#{keyword},'%'))
and a.location_flag = #{locationFlag}
and a.keeper_type = #{keeperType}
${dataScope} GROUP BY a.keeper_id order by a.keeper_sort

SELECT a.keeper_id,a.keeper_name,a.staff_id,a.tenant_id,a.industry_code
FROM
bm_gridkeeper a
WHERE a.staff_id = #{userId}
AND a.delete_flag = 0
and a.status = '0'
and a.tenant_id = #{tenantId,jdbcType=VARCHAR}
and a.industry_code = #{industryCode,jdbcType=VARCHAR}

SELECT ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{longitude},' ',#{latitude},')')), ST_GeomFromText(CONCAT('POINT(',a.longitude,' ',a.latitude,')')) ) as distance,a.keeper_id, a.grid_type, a.keeper_code, a.staff_id,a.staff_id as userId,a.staff_org_id, b.dept_name as staffOrgName, a.login_name, a.entry_time, a.wechat_number, a.party, a.education, a.is_special, a.special_type, a.major_type, a.keeper_aidentity, a.keeper_motto, a.personal_profile, a.is_grid_manager,a.keeper_type, a.keeper_sort, a.star_class, a.creator, a.create_time, a.modifier, a.update_time, a.delete_flag, a.versions, a.keeper_id_card_number, a.keeper_birth_date, a.keeper_address, a.keeper_phone_number, a.keeper_email, a.keeper_gender, a.keeper_name, a.longitude, a.latitude, a.take_point_time, a.tenant_id, a.industry_code, a.fj_url,a.province_id, a.city_id, a.county_id, a.`status`,a.location_flag,a.keeper_type,a.operating_duty,(case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as is_line FROM bm_gridkeeper a left join sys_dept b on a.staff_org_id = b.dept_id and b.del_flag = 0 WHERE a.delete_flag = 0 AND a.status='0' ${dataScope}
AND ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{longitude},' ',#{latitude},')')), ST_GeomFromText(CONCAT('POINT(',a.longitude,' ',a.latitude,')')) ) <= #{radius}
order by a.keeper_sort

SELECT a.keeper_id,a.keeper_name,b.grid_id, CONCAT( SUBSTRING( a.keeper_phone_number, 1, 3 ), '****', SUBSTRING( a.keeper_phone_number, 8 )) AS keeper_phone_number, a.keeper_phone_number AS phonePlainText, sys.AVATAR as keeperPhotoUrl, (case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as isLine FROM bm_gridkeeper a, bm_grid_keeper_ref b, sys_user sys WHERE a.keeper_id = b.keeper_id and a.staff_id = sys.USER_ID and b.grid_id in
#{item}
and a.tenant_id = #{tenantId,jdbcType=VARCHAR} and a.industry_code = #{industryCode,jdbcType=VARCHAR} AND a.delete_flag = 0 AND b.delete_flag = 0 AND a.keeper_type = '1'
and a.keeper_id != #{keeperId,jdbcType=BIGINT}

SELECT keeper_id, grid_type, keeper_code, staff_id, staff_org_id, login_name, entry_time, wechat_number, party, education, is_special, special_type, major_type, keeper_aidentity, keeper_motto, personal_profile, is_grid_manager, keeper_sort, star_class, creator, create_time, modifier, update_time, delete_flag, versions, keeper_id_card_number, keeper_birth_date, keeper_address, keeper_phone_number, keeper_email, keeper_gender, keeper_name, longitude, latitude, take_point_time, tenant_id, industry_code,fj_url,province_id, city_id, county_id, `status`,location_flag,keeper_type,operating_duty,(case when TIMESTAMPDIFF(MINUTE,take_point_time,now())<5 then '1' else '0' end) as is_line FROM bm_gridkeeper a WHERE a.staff_id = #{userId}
and a.tenant_id = #{tenantId}
and a.industry_code = #{industryCode}
AND a.delete_flag=0 limit 1

