SELECT distinct b.dept_name as staff_org_name, a.STATUS, a.keeper_id, a.grid_type, a.keeper_code, a.staff_id, a.staff_id as userId, a.staff_org_id, a.login_name, a.entry_time, a.wechat_number, a.party, a.education, a.is_special, a.special_type, a.major_type, a.keeper_aidentity, a.keeper_motto, a.personal_profile, a.is_grid_manager, a.keeper_sort, a.star_class, a.creator, a.create_time, a.modifier, a.update_time, a.delete_flag, a.versions, IF(a.keeper_id_card_number, CONCAT( SUBSTRING( a.keeper_id_card_number, 1, 6 ), '********', SUBSTRING( a.keeper_id_card_number, 15 )), NULL ) AS keeper_id_card_number, a.keeper_birth_date, a.keeper_address, a.keeper_phone_number as aes_phone_number, CONCAT(SUBSTRING( a.keeper_phone_number, 1, 3 ),'****',SUBSTRING( a.keeper_phone_number, 8 )) AS keeper_phone_number, a.keeper_email, a.keeper_gender, a.keeper_name, a.longitude, a.latitude, a.take_point_time, a.tenant_id, a.fj_url, (case when TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5 then '1' else '0' end) as is_line, a.province_id, a.city_id, a.county_id, a.location_flag, a.keeper_type, a.operating_duty, a.industry_code, a.app_ver_code FROM bm_gridkeeper a LEFT JOIN sys_dept b ON a.staff_org_id = b.dept_id and b.del_flag=0 LEFT JOIN bm_grid_keeper_ref re on a.keeper_id = re.keeper_id WHERE a.delete_flag = 0 and re.delete_flag = 0
and a.keeper_name like concat ('%',#{keeperName},'%')
and a.keeper_id_card_number like concat ('%',#{keeperIdCardNumber},'%')
and re.grid_id = #{gridId}
and a.keeper_type = #{keeperType}
and TIMESTAMPDIFF(MINUTE,a.take_point_time,now())<5
and (a.take_point_time is null or TIMESTAMPDIFF(MINUTE,a.take_point_time,now())>=5)
${dataScope}

select a.grid_id,a.grid_code,a.grid_name,b.keeper_id from bm_grid a left join bm_grid_keeper_ref b on a.grid_id = b.grid_id where a.delete_flag = '0' and b.delete_flag = '0'
and b.keeper_id in
#{item}

select task_id, conf_id, cnof_name, tenant_id, grid_id, grid_name, task_status, start_time, end_time, keeper_id, keeper_name, create_time, retroaction, fj_id, voice_url, video_url, inspection_time,conf_desc from bm_inspection_task
and FIND_IN_SET(#{keeperId},keeper_id)
and grid_id = #{gridId}

SELECT keeper_id,longitude,latitude FROM bm_gridkeeper WHERE tenant_id in
#{item}
AND longitude IS NOT NULL AND latitude IS NOT NULL

SELECT
keeper_id, keeper_type, keeper_code, is_grid_manager
FROM
bm_gridkeeper a
WHERE
a.staff_id = #{userId}

    and a.tenant_id = #{tenantId}


    and a.industry_code = #{industryCode}

AND a.delete_flag=0
limit 1

SELECT keeper_id, keeper_name, login_name, STATUS, longitude, latitude, province_id, city_id, county_id, location_flag, keeper_type, (case when TIMESTAMPDIFF(MINUTE,take_point_time,now())<5 then '1' else '0' end) as is_line FROM bm_gridkeeper a WHERE a.delete_flag = 0
and a.tenant_id = #{tenantId}
and a.industry_code = #{industryCode}
and a.longitude = #{longitude}
and a.latitude = #{latitude}
and a.province_id = #{provinceId}
and a.city_id = #{cityId}
and a.county_id = #{countyId}
and (a.province_id, a.city_id,a.county_id) IN
(#{item.provinceId}, #{item.cityId} , #{item.countyId})
${dataScope}
ORDER BY CASE WHEN SUBSTRING(a.keeper_name, 1, 1) REGEXP '[一-龥]' THEN firstPinyin(a.keeper_name) ELSE SUBSTRING(a.keeper_name, 1, 1) END
